import{_ as s,c as a,o as e,a2 as t}from"./chunks/framework.CQ12TVIp.js";const b=JSON.parse('{"title":"二开代码同步","description":"","frontmatter":{"ballcatVersion":"2.0.0"},"headers":[],"relativePath":"other/syncing-fork.md","filePath":"other/syncing-fork.md"}'),n={name:"other/syncing-fork.md"},i=t(`<h1 id="二开代码同步" tabindex="-1">二开代码同步 <a class="header-anchor" href="#二开代码同步" aria-label="Permalink to &quot;二开代码同步&quot;">​</a></h1><p>服务端代码不建议用户二开，而是以引入的方式进行使用，但是前端代码区别于服务端，开发一定会需要新增相关的业务页面或者组件信息。</p><p>此教程说明了如何在二开后方便的进行和源代码仓库进行同步。</p><blockquote><p>服务端代码如果必须二开，建议不要改动包名，且项目的业务代码在独立的仓库进行开发，方便后续升级</p></blockquote><h2 id="添加远程仓库" tabindex="-1">添加远程仓库 <a class="header-anchor" href="#添加远程仓库" aria-label="Permalink to &quot;添加远程仓库&quot;">​</a></h2><p>将源仓库配置为二开仓库的一个远程仓库</p><ul><li><p>在本地仓库中使用 <code>git remote -v</code> 查看远程状态。</p><blockquote><p>本地仓库的 origin 地址在哪都不影响，示例中假定其在 github 上，实际开发时，可能在 gitlab 或者 gitee 上</p></blockquote></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git remote -v</span></span>
<span class="line"><span># origin  https://github.com/YOUR_USERNAME/YOUR_FORK.git (fetch)</span></span>
<span class="line"><span># origin  https://github.com/YOUR_USERNAME/YOUR_FORK.git (push)</span></span></code></pre></div><ul><li>将源仓库添加为本地仓库的一个远程上有仓库</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git remote add upstream https://github.com/ballcat-projects/ballcat-ui-vue.git</span></span></code></pre></div><ul><li>再次查看状态确认是否配置成功。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git remote -v</span></span>
<span class="line"><span># origin    https://github.com/YOUR_USERNAME/YOUR_FORK.git (fetch)</span></span>
<span class="line"><span># origin    https://github.com/YOUR_USERNAME/YOUR_FORK.git (push)</span></span>
<span class="line"><span># upstream  https://github.com/ballcat-projects/ballcat-ui-vue.git (fetch)</span></span>
<span class="line"><span># upstream  https://github.com/ballcat-projects/ballcat-ui-vue.git (push)</span></span></code></pre></div><h2 id="同步更新" tabindex="-1">同步更新 <a class="header-anchor" href="#同步更新" aria-label="Permalink to &quot;同步更新&quot;">​</a></h2><ul><li>从上游仓库 fetch 分支和提交点，传送到本地，并会被存储在一个本地分支 upstream/master <code>git fetch upstream</code></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git fetch upstream</span></span>
<span class="line"><span># remote: Counting objects: 75, done.</span></span>
<span class="line"><span># remote: Compressing objects: 100% (53/53), done.</span></span>
<span class="line"><span># remote: Total 62 (delta 27), reused 44 (delta 9)</span></span>
<span class="line"><span># Unpacking objects: 100% (62/62), done.</span></span>
<span class="line"><span># From https://github.com/ballcat-projects/ballcat-ui-vue.git</span></span>
<span class="line"><span>#  * [new branch]      master     -&gt; upstream/master</span></span></code></pre></div><ul><li>切换到本地主分支(如果不在的话) <code>git checkout master</code></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git checkout master</span></span>
<span class="line"><span># Switched to branch &#39;master&#39;</span></span></code></pre></div><ul><li>把 upstream/master 分支合并到本地 master 上，这样就完成了同步，并且不会丢掉本地修改的内容。 <code>git merge upstream/master</code></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git merge upstream/master</span></span>
<span class="line"><span># Updating a422352..5fdff0f</span></span>
<span class="line"><span># Fast-forward</span></span>
<span class="line"><span>#  README                    |    9 -------</span></span>
<span class="line"><span>#  README.md                 |    7 ++++++</span></span>
<span class="line"><span>#  2 files changed, 7 insertions(+), 9 deletions(-)</span></span>
<span class="line"><span>#  delete mode 100644 README</span></span>
<span class="line"><span>#  create mode 100644 README.md</span></span></code></pre></div><ul><li>这时将合并后的代码推送到自己仓库的远程分支上，即可完成此次同步</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p>分支无法合并，控制台打印如下错误信息：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fatal:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refusing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unrelated</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> histories</span></span></code></pre></div><p>这一般是因为，你的库并没有源仓库的提交历史，git 认为这两个仓库没有关联，所以拒绝了合并命令。 这时通过添加 <code>--allow-unrelated-histories</code> 参数来允许合并即可。</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream/master</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-unrelated-histories</span></span></code></pre></div><h2 id="原文地址" tabindex="-1">原文地址 <a class="header-anchor" href="#原文地址" aria-label="Permalink to &quot;原文地址&quot;">​</a></h2><p><a href="https://gaohaoyang.github.io/2015/04/12/Syncing-a-fork/" target="_blank" rel="noreferrer">https://gaohaoyang.github.io/2015/04/12/Syncing-a-fork/</a></p><p><a href="https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/about-forks" target="_blank" rel="noreferrer">https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/about-forks</a></p><p><a href="https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/configuring-a-remote-for-a-fork" target="_blank" rel="noreferrer">https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/configuring-a-remote-for-a-fork</a></p>`,29),p=[i];function l(o,c,r,h,d,u){return e(),a("div",null,p)}const m=s(n,[["render",l]]);export{b as __pageData,m as default};
